SELECT investor_id, investor_name, risk_tolerance
FROM ATOM_ENTITY_INVESTOR_PROFILE_001
WHERE risk_tolerance NOT IN ('Aggressive', 'Conservative', 'Moderate');

SELECT COUNT(portfolio_health_id) AS missing_liquidity_score_count
FROM ATOM_ENTITY_PORTFOLIO_HEALTH_001
WHERE liquidity_score IS NULL;

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?amount) AS ?net_cash_flow) WHERE {
  ?cf a wm:CashFlow ;
      wm:date ?date ;
      wm:amount ?amount .
  FILTER ( ?date >= "2025-01-01"^^xsd:date && ?date <= "2025-12-31"^^xsd:date )
}

